import {TASKS,TASK_INFO,LABELS,PROTOCOLS,planTasks,isTracking,summarizeTrials,cm360,RANGES,rangeCandidates,validProfile} from './engine.js';
export const fmt=(n,p=2)=>n==null?'—':Number(n).toLocaleString('pt-BR',{maximumFractionDigits:p});
export const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});
const protocol=p=>(PROTOCOLS[p.protocol]?.label||'Diagnóstico')+(p.version>=2?' · v2':' · v1');
export const heading=(label,title,description)=>`<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${description}</p></div></div>`;
const metric=(label,value,unit,foot)=>`<div class="metric"><div class="metric-label">${label}</div><div class="number">${value}<small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`;
export function workouts(selected){return `<div class="exercise-list"><div class="exercise-list-head"><span>Exercício</span><span>Objetivo</span><span>Entrada</span><span></span></div>${TASKS.map((t,i)=>`<a class="exercise-row ${selected===t?'selected':''}" href="#practice/${t}"><span class="exercise-name"><span class="exercise-index">0${i+1}</span><span><strong>${LABELS[t]}</strong><small>${TASK_INFO[t].group}</small></span></span><span class="exercise-description">${TASK_INFO[t].description}</span><span class="exercise-input">${isTracking(t)?'Acompanhar':'Clicar'}</span><span class="row-arrow" aria-hidden="true">→</span></a>`).join('')}</div>`;}
export function dashboard({profile,history,pending,practiceHistory}){
  const last=history[0],rec=last?.result.recommendation;
  return `${heading('PAINEL DE TREINO','Visão geral','Seu perfil, exercícios e resultados em um só lugar.')}<div class="notice mobile-notice">Os exercícios precisam de um computador com mouse.</div><div class="metric-grid">${metric('Sensibilidade',fmt(profile.sens,3),'VAL','Perfil atual')}${metric('Mouse',fmt(profile.dpi,0),'DPI',fmt(profile.dpi*profile.sens,1)+' eDPI')}${metric('Distância por giro',fmt(cm360(profile.dpi,profile.sens),1),'cm','Rotação de 360°')}${metric('Última recomendação',rec?fmt(rec.sens,3):'—',rec?'VAL':'',last?date(last.createdAt):'Nenhum diagnóstico concluído')}</div><section class="session-banner"><div><div class="eyebrow">DIAGNÓSTICO DE SENSIBILIDADE</div><h2>${pending?'Sessão em andamento':'Compare seu desempenho em seis exercícios'}</h2><p>${pending?pending.trials.length+' de '+pending.plan.rounds.length+' rodadas salvas. Retome a próxima quando quiser.':'Sensibilidades baixas e altas, condições repetidas e uma análise por habilidade.'}</p></div><a class="btn primary" href="#diagnostic">${pending?'Retomar sessão':'Configurar diagnóstico'} <span>→</span></a></section><div class="section-heading"><h2>Biblioteca de exercícios</h2><span class="muted">06 cenários</span></div>${workouts()}<div class="bottom-grid"><section class="panel"><div class="section-heading"><h2>Atividade recente</h2><a class="text-link" href="#history">Ver histórico</a></div>${last?`<div class="session-row"><div><strong>Diagnóstico ${protocol(last.plan)}</strong><p>${date(last.createdAt)} · ${last.trials.length} rodadas</p></div><a class="btn ghost" href="#result/${esc(last.id)}">Abrir análise</a></div>`:'<div class="empty-inline"><p>Nenhum diagnóstico concluído. Configure uma sessão para criar sua primeira referência.</p></div>'}<div class="activity-count">${practiceHistory.length} treinos livres registrados <span>·</span> ${history.length} diagnósticos</div></section><section class="panel"><h2>Antes de começar</h2><ol class="checklist"><li>Confira o DPI e a sensibilidade do perfil.</li><li>Faça a calibração física se ainda não conferiu o giro.</li><li>Aqueça por alguns minutos e mantenha a mesma postura.</li></ol><a class="text-link" href="#settings">Revisar configurações</a></section></div>`;
}
export function protocolOptions(profile,range='extended',selected='complete'){
  const count=validProfile(profile)?rangeCandidates(profile,range).length:null;
  return Object.entries(PROTOCOLS).map(([id,p])=>`<label class="radio-card"><span><input type="radio" name="protocol" value="${id}" ${id===selected?'checked':''}> ${p.label}</span><strong>${count?fmt(p.tasks.length*count*p.repeats*p.seconds/60,2)+' min':'—'}</strong><small>${count?p.tasks.length*count*p.repeats:'—'} rodadas de ${p.seconds}s · ${p.tasks.length} exercícios · ${p.repeats} ${p.repeats>1?'repetições':'repetição'}</small><small>${p.description}</small></label>`).join('');
}
export function rangePreview(profile,range='extended'){
  if(!validProfile(profile))return '<p class="caption">Informe um DPI e uma sensibilidade válidos para calcular os valores e a duração.</p>';
  const candidates=rangeCandidates(profile,range);
  return `<details style="margin-top:15px"><summary class="text-link">${candidates.length} sensibilidades · ${fmt(candidates[0],3)} a ${fmt(candidates.at(-1),3)} VAL · ver valores</summary><div class="table-wrap"><table><thead><tr><th>Sensibilidade</th><th>eDPI</th><th>cm/360°</th></tr></thead><tbody>${candidates.map(s=>`<tr><td>${fmt(s,3)}</td><td>${fmt(profile.dpi*s,1)}</td><td>${fmt(cm360(profile.dpi,s),1)}</td></tr>`).join('')}</tbody></table></div></details><p class="caption">${range==='extended'?'A busca ampla inclui valores baixos e altos. Use a triagem para explorar e depois refine a região com melhor resultado.':'Esta faixa concentra os testes ao redor do valor inicial.'} Os valores são limitados a 0,01–5 e duplicados são removidos; o tempo acima já considera isso.</p>`;
}
export function diagnostic({pending,profileFields,refine=false,profile={dpi:800,sens:.35,calibration:1}}){
  if(pending){const done=pending.trials.length,total=pending.plan.rounds.length,next=pending.plan.rounds[done];return `${heading('DIAGNÓSTICO','Sessão em andamento',protocol(pending.plan)+' · '+pending.plan.profile.dpi+' DPI')}<section class="panel"><div class="section-heading"><h2>${done} / ${total} rodadas concluídas</h2><span class="chip">${fmt(done/total*100,0)}%</span></div><div class="progress"><span style="width:${done/total*100}%"></span></div><p>${next?'Próximo exercício: '+LABELS[next.task]+'. A sensibilidade continua oculta durante a rodada.':'Todas as rodadas foram salvas. Abra a análise para concluir.'}</p><div class="actions"><button class="btn primary" data-action="resume">${next?'Retomar sessão':'Abrir análise'}</button><button class="btn ghost" data-action="discard">Descartar sessão</button></div></section>`;}
  return `${heading('DIAGNÓSTICO','Configurar sessão','Escolha a profundidade do teste. Pausas e adaptação não entram no tempo estimado.')}<div class="split"><form id="diagnostic-form" class="panel setup-panel"><h2>01 <span class="muted">/</span> Perfil de entrada</h2>${profileFields()}<h2 class="form-section">02 <span class="muted">/</span> Protocolo</h2><div id="protocol-options" class="protocols">${protocolOptions(profile,refine?'refine':'extended')}</div><label class="field">Faixa de sensibilidades<select name="range">${Object.entries(RANGES).map(([id,r])=>`<option value="${id}" ${(refine?id==='refine':id==='extended')?'selected':''}>${r.label}</option>`).join('')}</select></label><div id="range-preview">${rangePreview(profile,refine?'refine':'extended')}</div><div class="notice">A sensibilidade fica oculta durante o teste. A ordem muda entre repetições; os alvos e trajetórias são equivalentes para cada candidato. Há uma sugestão de pausa a cada 10 rodadas.</div><button class="btn primary" type="submit">Iniciar sessão →</button><p class="error" id="form-error" role="alert"></p></form><div class="stack"><section class="panel"><h2>O que será medido</h2><dl class="measure-list"><dt>Precisão e velocidade</dt><dd>Acertos por segundo, precisão e tempo mediano de aquisição.</dd><dt>Controle do movimento</dt><dd>Eficiência do caminho e ultrapassagens detectadas em alvos estáticos.</dd><dt>Acompanhamento</dt><dd>Tempo no alvo, erro angular e distribuição do erro.</dd><dt>Repetibilidade</dt><dd>Variação da nota, líder de cada repetição e qualidade da coleta.</dd></dl></section><section class="panel"><h2>Quando o resultado é inconclusivo</h2><p>Poucos acertos, pouco movimento no tracking ou renderização abaixo de 45 FPS impedem uma recomendação automática. Você ainda pode consultar todas as medições.</p><a class="text-link" href="#method">Ler critérios e limitações</a></section></div></div>`;
}
export function practice({task,profile,practiceHistory}){
  const selected=TASKS.includes(task)?task:'flick',recent=practiceHistory.filter(h=>h.trial.task===selected).slice(0,8);
  return `${heading('TREINO LIVRE','Exercícios','Treine uma habilidade por vez. Os resultados ficam registrados sem alterar o diagnóstico.')}<section class="panel practice-setup"><div><span class="eyebrow">${TASK_INFO[selected].group}</span><h2>${LABELS[selected]}</h2><p>${TASK_INFO[selected].description}</p></div><form id="practice-form"><div class="form-grid"><label class="field">Exercício<select name="task">${TASKS.map(t=>`<option value="${t}" ${t===selected?'selected':''}>${LABELS[t]}</option>`).join('')}</select></label><label class="field">Duração<select name="seconds"><option value="30">30 segundos</option><option value="60">60 segundos</option><option value="90">90 segundos</option></select></label></div><div class="actions"><button class="btn primary" type="submit">Iniciar treino →</button><span class="muted">${fmt(profile.sens,3)} VAL · ${profile.dpi} DPI</span></div></form></section>${workouts(selected)}<section class="panel" style="margin-top:24px"><div class="section-heading"><h2>Últimos treinos · ${LABELS[selected]}</h2><span class="muted">${recent.length} registros</span></div>${recent.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Sens. / DPI</th><th>Tempo</th><th>${isTracking(selected)?'No alvo':'Precisão'}</th><th>${isTracking(selected)?'Erro médio':'Acertos/s'}</th><th>Aquisição mediana</th></tr></thead><tbody>${recent.map(h=>{const s=summarizeTrials([h.trial]);return `<tr><td>${date(h.createdAt)}</td><td>${fmt(h.trial.sens,3)} / ${h.profile.dpi}</td><td>${h.trial.seconds}s</td><td>${fmt(isTracking(selected)?s.onTargetPercent:s.accuracy,1)}%</td><td>${fmt(isTracking(selected)?s.meanError:s.hitsPerSecond,2)}${isTracking(selected)?'°':''}</td><td>${isTracking(selected)?'—':fmt(s.medianMs,0)+' ms'}</td></tr>`;}).join('')}</tbody></table></div><p class="caption">Compare registros com o mesmo DPI, sensibilidade, duração e calibração. Treinos não usam a nota normalizada do diagnóstico.</p>`:'<p class="empty-copy">Ainda não há treinos registrados para este exercício.</p>'}</section>`;
}
export function historyPage({history}){return `${heading('REGISTROS','Histórico de diagnósticos','Resultados preservados com a versão e as condições de cada teste.')}<section class="panel"><div class="section-heading"><h2>${history.length} sessões</h2><button class="btn ghost" data-action="export-all">Exportar dados</button></div>${history.length?history.map(h=>`<div class="session-row"><div><strong>${date(h.createdAt)}</strong><p>${protocol(h.plan)} · ${h.plan.profile.dpi} DPI · ${h.trials.length} rodadas</p></div><div><span class="number">${h.result.recommendation?fmt(h.result.recommendation.sens,3):'—'}</span><small class="muted"> ${h.result.stable?'Consistente':'Provisório / inconclusivo'}</small></div><a class="btn ghost" href="#result/${esc(h.id)}">Ver análise</a></div>`).join(''):'<div class="empty-state"><h2>Nenhum diagnóstico concluído</h2><p>As análises aparecerão aqui assim que você concluir uma sessão.</p><a class="btn primary" href="#diagnostic">Configurar diagnóstico</a></div>'}</section>`;}
const number=(n,suffix='',p=1)=>n==null?'—':fmt(n,p)+suffix;
function resultNotes(record){const r=record.result,notes=[];if(!r.recommendation)notes.push('A coleta não sustenta uma recomendação automática. Consulte os alertas por sensibilidade antes de repetir.');else{
  if(r.tied)notes.push('Há sensibilidades a até 5 pontos do líder. A indicação favorece o valor mais próximo da sua configuração inicial.');
  if(r.edge)notes.push('A indicação está na borda da faixa testada. Explore uma nova faixa antes de estreitar a busca.');
  if(!r.stable)notes.push('A diferença ou a repetibilidade ainda não é suficiente para classificar o resultado como consistente.');
  if(r.stable)notes.push('O mesmo candidato liderou todas as repetições, com margem acima de 5 pontos e variação de até 15%. Confirme em outro dia.');
}if(r.lastChange!=null&&Math.abs(r.lastChange)>8)notes.push(`A nota média ${r.lastChange>0?'subiu':'caiu'} ${fmt(Math.abs(r.lastChange),1)} pontos entre a primeira e a última repetição. Aprendizagem ou cansaço podem ter influenciado; o teste não distingue essas causas.`);return notes;}
export function results(record){
  const r=record.result,rec=r.recommendation,tasks=planTasks(record.plan),rows=[...r.rows].sort((a,b)=>a.sens-b.sens),v2=r.version>=2;
  return `${heading('RELATÓRIO DE SESSÃO','Análise de sensibilidade',date(record.createdAt)+' · '+protocol(record.plan)+' · '+record.plan.profile.dpi+' DPI · '+record.plan.candidates.length+' sensibilidades')}<section class="result-summary"><div><div class="eyebrow">${rec?'RECOMENDAÇÃO PARA TESTAR NO JOGO':'RESULTADO INCONCLUSIVO'}</div><div class="result-number">${rec?fmt(rec.sens,3):'—'} <small>VAL</small></div><p>${rec?fmt(rec.sens*record.plan.profile.dpi,1)+' eDPI · '+fmt(cm360(record.plan.profile.dpi,rec.sens),1)+' cm/360°':'Os dados permanecem disponíveis abaixo.'}</p></div><div class="result-summary-right"><span class="chip ${r.stable?'positive':''}">${r.stable?'Consistente nesta sessão':rec?'Indicação provisória':'Coleta insuficiente'}</span>${rec?`<div class="actions"><button class="btn primary" data-action="apply-result">Aplicar ao perfil</button><button class="btn ghost" data-action="copy-result">Copiar</button></div>`:''}<span class="caption">O Valorant é ajustado manualmente.</span></div></section><div class="metric-grid">${metric('Líder da sessão',r.signal?fmt(r.top.sens,3):'—','VAL','Maior nota combinada')}${metric('Diferença para o 2º',fmt(r.gap,1),'pt','Na pontuação relativa')}${metric('Faixa próxima',r.signal?fmt(r.range[0],3)+' – '+fmt(r.range[1],3):'—','','Até 5 pontos do líder')}${metric('Repetições por condição',String(record.plan.repeats||(record.plan.protocol==='quick'?1:2)),'',v2?number(r.top.variation,'% de variação do líder'):'Protocolo anterior')}</div><section class="panel"><div class="section-heading"><h2>Comparação geral</h2><span class="muted">Maior nota é melhor</span></div><div class="table-wrap"><table><thead><tr><th>Sens.</th><th>Nota combinada</th><th>Repetições</th><th>Variação</th><th>Coleta</th></tr></thead><tbody>${rows.map(row=>`<tr class="${rec?.sens===row.sens?'winner':''}"><td><strong>${fmt(row.sens,3)}</strong>${rec?.sens===row.sens?' <span class="table-marker">indicada</span>':''}</td><td><div class="score-cell"><div class="bar-track"><span style="width:${row.score}%"></span></div><span>${fmt(row.score,1)}</span></div></td><td>${row.repeatScores?row.repeatScores.map(s=>fmt(s,1)).join(' / '):'—'}</td><td>${row.repeatScores?.length>1?fmt(row.variation,1)+'%':'—'}</td><td>${!v2?'v1':row.eligible?'Suficiente':`<span class="warning">Revisar</span>`}</td></tr>`).join('')}</tbody></table></div><p class="caption">Nota relativa aos candidatos desta sessão. A variação é o desvio padrão dividido pela média das notas por repetição; não é confiança estatística.</p></section><div class="analysis-grid"><section class="panel"><h2>Leitura do resultado</h2><ul class="findings">${resultNotes(record).map(s=>`<li>${s}</li>`).join('')}</ul>${rec?'<button class="btn secondary" data-action="refine-result">Preparar refinamento ±10%</button>':''}</section><section class="panel"><h2>Melhor candidato por habilidade</h2>${tasks.map(t=>{const ranking=[...rows].sort((a,b)=>(b.tasks[t]||0)-(a.tasks[t]||0)),difference=ranking[0].tasks[t]-(ranking[1]?.tasks[t]||0);return `<div class="skill-row"><span>${LABELS[t]}</span><strong>${fmt(ranking[0].sens,3)}</strong><small>${difference<=5?'próximos':'+'+fmt(difference,1)+' pt'}</small></div>`;}).join('')}<p class="caption">O melhor valor pode mudar entre tarefas. A recomendação geral usa os pesos do protocolo.</p></section></div>${v2&&rows.some(row=>row.reasons.length)?`<section class="panel quality-panel"><h2>Alertas da coleta</h2>${rows.filter(row=>row.reasons.length).map(row=>`<p><strong>${fmt(row.sens,3)}:</strong> ${row.reasons.map(esc).join('; ')}.</p>`).join('')}</section>`:''}<section class="panel detail-panel"><div class="section-heading"><h2>Métricas por exercício</h2><label class="field compact-field"><span class="sr-only">Exercício da análise</span><select id="analysis-task">${tasks.map(t=>`<option value="${t}">${LABELS[t]}</option>`).join('')}</select></label></div><div id="analysis-detail">${analysisDetail(record,tasks[0])}</div></section>${v2?`<section class="panel"><h2>Condições da sessão</h2><div class="conditions"><span>${record.trials.length} rodadas</span><span>${fmt(r.summary.medianFps,0)} FPS mediano</span><span>${r.summary.pauses} pausas durante rodadas</span><span>Calibração ${fmt(record.plan.profile.calibration,3)}</span></div><p class="caption">${r.summary.lowFpsRounds} rodadas abaixo de 45 FPS. Entrada sem aceleração é solicitada, mas nem todo navegador confirma o suporte. Fontes e métricas completas estão na exportação.</p></section>`:'<div class="notice">Sessão v1: as métricas detalhadas de movimento não eram coletadas. Os resultados originais foram preservados.</div>'}<div class="actions"><button class="btn ghost" data-action="export-result">Exportar sessão em JSON</button><a class="btn ghost" href="#diagnostic">Novo diagnóstico</a><a class="text-link" href="#method">Critérios do método</a></div>`;
}
export function analysisDetail(record,task){
  const track=isTracking(task),rows=[...record.result.rows].sort((a,b)=>a.sens-b.sens),summaries=rows.map(row=>({sens:row.sens,d:row.details?.[task]||summarizeTrials(record.trials.filter(t=>t.task===task&&t.sens===row.sens))}));
  const recommendation=record.result.recommendation?.sens||record.result.top.sens,d=summaries.find(s=>s.sens===recommendation)?.d;
  return `<p>${TASK_INFO[task].description}</p><div class="table-wrap"><table><thead><tr><th>Sens.</th>${track?'<th>Tempo no alvo</th><th>Erro médio</th><th>Erro P90</th>':'<th>Precisão</th><th>Acertos/s</th><th>Aquisição mediana</th><th>Aquisição P90</th><th>Caminho eficiente</th><th>Ultrapassagens</th>'}<th>Amostra</th></tr></thead><tbody>${summaries.map(({sens,d})=>`<tr class="${sens===recommendation?'winner':''}"><td>${fmt(sens,3)}</td>${track?`<td>${number(d.onTargetPercent,'%')}</td><td>${number(d.meanError,'°',2)}</td><td>${number(d.p90Error,'°',2)}</td>`:`<td>${number(d.accuracy,'%')}</td><td>${number(d.hitsPerSecond,'',2)}</td><td>${number(d.medianMs,' ms',0)}</td><td>${number(d.p90Ms,' ms',0)}</td><td>${number(d.efficiency,'%')}</td><td>${task==='strafe'?'—':d.targets?d.overshoots+' / '+d.targets:'—'}</td>`}<td>${track?d.samples+' amostras':d.hits+' acertos / '+d.shots+' cliques'}</td></tr>`).join('')}</tbody></table></div><p class="caption">${track?'Erro angular: distância entre a mira e o centro do alvo, em graus. O P90 cobre 90% das amostras de erro.':'Aquisição: tempo entre o aparecimento do alvo e o acerto, não tempo de reação puro. P90: 90% dos acertos ocorreram até esse tempo. Eficiência é caminho direto / caminho percorrido; ultrapassagem é uma heurística de passar além do alvo e retornar.'}</p>${track&&d?.samples?`<div class="tracking-detail"><div><h3>Distribuição do erro · ${fmt(recommendation,3)}</h3><p class="caption">Tempo em cada região ao redor do alvo. O centro representa até meio raio por eixo; bordas acumulam erros além da grade.</p><div class="heatmap" role="img" aria-label="Distribuição do erro de mira em uma grade de sete por sete, com centro no alvo">${d.heatmap.map((n,i)=>`<span class="heat-cell ${i===24?'heat-center':''}" style="--intensity:${Math.max(.035,n/Math.max(1,...d.heatmap))}" title="Linha ${Math.floor(i/7)+1}, coluna ${i%7+1}: ${fmt(n/1000,2)} s"></span>`).join('')}</div><span class="caption">Mais claro = mais tempo · dados deste exercício</span></div><div><h3>Tempo no alvo durante a rodada</h3>${trackingChart(record,task,recommendation)}<p class="caption">Média ponderada por segundo entre repetições, na sensibilidade indicada acima. A trajetória muda entre repetições.</p></div></div>`:''}`;
}
function trackingChart(record,task,sens){const series=[];record.trials.filter(t=>t.task===task&&t.sens===sens).forEach(t=>t.telemetry?.seconds?.forEach((s,i)=>{if(!s)return;series[i]??={ms:0,on:0};series[i].ms+=s.ms;series[i].on+=s.on;}));if(series.length<2)return '<p>Sem amostras temporais.</p>';const points=series.map((s,i)=>`${35+i/(series.length-1)*365},${140-(s.ms?s.on/s.ms:0)*110}`).join(' ');return `<svg class="trend-chart" viewBox="0 0 430 175" role="img" aria-label="Porcentagem de tempo no alvo por segundo"><path d="M35 30H400M35 85H400M35 140H400" class="chart-grid"/><text x="0" y="34">100%</text><text x="7" y="89">50%</text><text x="14" y="144">0%</text><polyline points="${points}" fill="none" class="chart-line"/><text x="35" y="165">1s</text><text x="380" y="165">${series.length}s</text></svg>`;}
export function method(){return `${heading('DOCUMENTAÇÃO','Método e métricas','Protocolo v2 · comparação individual de sensibilidade')}<article class="panel prose"><h2>Desenho da sessão</h2><p>A triagem usa flick, microajuste e tracking contínuo, uma vez por sensibilidade. O completo usa seis exercícios, duas vezes por condição. O aprofundado repete três vezes. A faixa ampla compara nove multiplicadores da sensibilidade inicial: 0,25×, 0,5×, 0,75×, 1×, 1,5×, 2×, 3×, 4× e 6×. A faixa próxima da atual mantém 70%, 85%, 100%, 115% e 130%; o refinamento usa 90%, 95%, 100%, 105% e 110%. A configuração mostra os valores exatos, eDPI, distância de giro e a duração recalculada. A mesma quantidade de rodadas e repetições é usada para cada valor.</p><p>A ordem inicial é embaralhada. Entre repetições, a posição dos candidatos é rotacionada; a ordem dos exercícios também muda. A semente da sequência de alvos e da trajetória é a mesma para todos os candidatos de uma tarefa e repetição. Isso reduz diferenças de dificuldade e posição, mas não elimina aprendizagem, adaptação ou cansaço.</p><p>Valores são limitados a 0,01–5, arredondados a três casas e duplicados são removidos. Por isso, faixas próximas aos limites podem ter menos rodadas. Três segundos de adaptação, pausas e tempo fora de foco não pontuam. Rodadas interrompidas são reiniciadas ao reabrir a sessão. Versões antigas mantêm os exercícios e a análise originais.</p><h2>Pontuação e pesos</h2><p>Exercícios de clique: acertos por segundo × raiz quadrada da precisão. Exercícios de tracking: porcentagem do tempo ativo no alvo. A média das repetições de cada tarefa é normalizada pelo melhor candidato da tarefa. Assim, 100 pontos significa o melhor desempenho nesta sessão, não 100% de precisão.</p><div class="table-wrap"><table><thead><tr><th>Exercício</th><th>Completo / aprofundado</th></tr></thead><tbody>${TASKS.map(t=>`<tr><td>${LABELS[t]}</td><td>${fmt(TASK_INFO[t].weight*100,0)}%</td></tr>`).join('')}</tbody></table></div><p>Na triagem, os pesos são 40% flick, 40% microajuste e 20% tracking contínuo. Os pesos são heurísticos; não representam um modelo validado de desempenho no Valorant.</p><h2>Dados adicionais</h2><dl class="measure-list"><dt>Aquisição mediana e P90</dt><dd>Tempo até acertar cada alvo. Inclui planejamento, movimento e cliques errados; não é uma medida pura de reflexo. O P90 indica o tempo abaixo do qual ocorreram 90% dos acertos.</dd><dt>Eficiência do caminho</dt><dd>Distância angular inicial até o alvo dividida pelo caminho percorrido, limitada a 100%. Medida em alvos estáticos. Não altera a pontuação, pois estilos de movimento diferentes podem ser igualmente eficazes.</dd><dt>Ultrapassagens</dt><dd>Acertos em que a mira passou além do centro por mais de um raio, próximo ao eixo do movimento. É uma heurística por alvo acertado, não um diagnóstico de sensibilidade alta.</dd><dt>Erro de tracking</dt><dd>Média angular ponderada pelo tempo. P90 usa amostras com espaçamento mínimo de 50 ms. O mapa agrega tempo em regiões de um raio ao redor do alvo; as bordas absorvem valores externos.</dd><dt>Variação</dt><dd>Desvio padrão populacional / média das notas de cada repetição. Com apenas duas ou três repetições, é descritivo, não uma estimativa estatística robusta.</dd></dl><h2>Qualidade e recomendação</h2><p>Cada candidato deve ter, em cada tarefa de clique, média de ao menos 5 acertos por rodada. No tracking, precisa de pelo menos 2% de tempo no alvo e de movimento angular acumulado de 0,25° por segundo em cada rodada. A coleta deve cobrir a duração e nenhuma rodada pode ter média abaixo de 45 FPS. São limites heurísticos mínimos; não provam qualidade científica. Se uma condição falhar, a comparação completa é marcada inconclusiva e os dados continuam visíveis.</p><p>Os candidatos a até 5 pontos do líder formam a faixa próxima. A indicação favorece o candidato dessa faixa mais próximo da sensibilidade inicial. “Consistente nesta sessão” exige duas ou mais repetições, mesmo líder em todas, margem maior que 5 pontos e variação do líder de até 15%. Uma sessão não garante melhora em partidas. Confirme conforto e resultado em outro dia.</p><h2>Equivalência com o jogo</h2><p>Adotamos yaw comunitário de 0,07° por unidade de movimento × sensibilidade, FOV horizontal de 103° em 16:9 e campo vertical constante em outras proporções. O DPI só entra em eDPI e cm/360°. A entrada sem aceleração é solicitada ao navegador, mas o suporte nem sempre é confirmado. Calibre fisicamente. ADS, recuo, movimentação e latência do jogo não são simulados.</p><p><code>eDPI = DPI × sensibilidade</code><br><code>cm/360° = 914,4 ÷ (DPI × sensibilidade × 0,07)</code></p><h2>Referências e dados</h2><p><a href="https://developer.mozilla.org/en-US/docs/Web/API/Pointer_Lock_API" target="_blank" rel="noreferrer">Pointer Lock · MDN</a> · <a href="https://www.w3.org/TR/pointerlock/" target="_blank" rel="noreferrer">Especificação W3C</a> · <a href="https://github.com/Pratilectron/valotrainer" target="_blank" rel="noreferrer">Parâmetros comunitários · Valotrainer</a></p><p>Treinos e diagnósticos ficam neste navegador. Exportação JSON inclui as métricas e condições. Histórico limitado a 100 diagnósticos e 150 treinos livres. O algoritmo é próprio; não reproduz o método proprietário do Oblivity.</p></article>`;}
